 function mapReady(){if(map)return;map=createPlacesMap({container:$('places-map'),L,offlineMaps,pinHTML:icon('footprint'),document,events,network,onPick:id=>open(id),onMove:p=>{const moved=!center||proximityKm(center,{lat:p.lat,lng:p.lng})>=.1;if(moved)locationRequest++;$('places-search-area').hidden=!moved;},onStatus:({state,message})=>{$('places-map-status').textContent=state==='error'?'The map background could not load. Tap Refresh to try again; listed places are still available.':message;}});map.setVisible(active&&mapVisible);if(center)map.center(center,Number($('places-radius').value));}
