 const dateTime=value=>new Date(value).toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
 function renderRecent(){const rows=client.recent?.()??[];$('places-saved-count').textContent=String(rows.length);$('places-saved-list').innerHTML=rows.map(e=>`<button type="button" class="saved-search" data-recall-search="${esc(e.id)}"><strong>${esc(discoveryGroup(e.params.groupId).filters.find(f=>f.id===e.params.filterId)?.label??discoveryGroup(e.params.groupId).label)} · ${e.params.radius/1000} km</strong><span>${esc(e.label)} · ${e.count} places</span><small>${esc(dateTime(e.at))}${e.retained?'':' · this session only'}</small></button>`).join('');$('places-clear-searches').disabled=!rows.length;$('places-cache-status').textContent=rows.length?(client.storageAvailable?'Kept on this device. Up to 30 recent searches; older entries may be removed when storage fills.':'Some results are only available for this session. This device could not retain every search for reopening.'):'Completed searches will appear here. Your saved footprints are separate.';}
