  $('places-results-count').textContent=(displayLabel?`${displayLabel} · `:'')+`${rows.length} ${rows.length===1?'place':'places'}${query?' matching your filter':''}${limited?' · this busy area may contain more':''}${busy?' · updating…':''}`;
