  $('places-types').onclick=e=>{const b=e.target.closest('[data-discovery-filter]');if(!b||b.dataset.discoveryFilter===filterId)return;filterId=b.dataset.discoveryFilter;categories();void search();};
  $('places-results').onclick=e=>{const b=e.target.closest('[data-discovery-place]');if(b)open(b.dataset.discoveryPlace);};$('places-more').onclick=more;
  $('places-filter').oninput=e=>{query=e.target.value.trim().toLocaleLowerCase();limit=30;render();};$('places-radius').onchange=()=>{if(center)map?.center(center,Number($('places-radius').value));void search();};$('places-refresh').onclick=()=>{map?.retry();const p=map?.getCenter()??center;if(p){const moved=!center||proximityKm(center,p)>=.1;setArea(moved?p:center,moved?'Map area':areaLabel);$('places-search-area').hidden=true;void search(true);}};
